/**
 * Writes tests/fixtures/laws.sql, the database CI tests the law pages against.
 *
 * Source: a scratch MySQL filled from gesetze-im-internet.de, never production:
 *   DB_URL=mysql://root@127.0.0.1:3306/lawnetz npx drizzle-kit push --force
 *   DB_URL=... npx tsx scripts/sync-law-to-db.ts gg arbzg burlg bgb stgb hgb
 *   (English: insert the laws rows for englisch_gg and englisch_bgb, then run
 *   scrapeEnglishLaw from scripts/scrape-en-law.cjs for both)
 *   DB_URL=... node tests/fixtures/make-db-fixture.mjs
 *
 * Small laws go in whole. Of the big codes only the norms the glossary points
 * to, so tests/e2e/glossary.spec.ts can check every entry against its law,
 * and the headings directly above those norms.
 */
import { writeFileSync } from 'node:fs';
import mysql from 'mysql2/promise';
import glossary from '../../src/data/glossary.json' with { type: 'json' };

const WHOLE = ['gg', 'arbzg', 'burlg', 'englisch_gg'];
const entries = [...glossary.de, ...glossary.en];
const PARTS = [...new Set(entries.map((e) => e.law))].filter((l) => !WHOLE.includes(l));

const conn = await mysql.createConnection(process.env.DB_URL);
const [laws] = await conn.query('SELECT * FROM laws WHERE slug IN (?) ORDER BY slug', [[...WHOLE, ...PARTS]]);
const [norms] = await conn.query(
	`SELECT * FROM norms WHERE law_slug IN (?) OR id IN (?) ORDER BY law_slug, order_index`,
	[WHOLE, entries.filter((e) => PARTS.includes(e.law)).map((e) => `${e.law}:${e.norm}`)],
);
// Headings of the whole laws; of the others those right above a norm kept.
const kept = new Set(norms.map((n) => `${n.law_slug}:${n.order_index}`));
const [outline] = await conn.query('SELECT * FROM law_outline WHERE law_slug IN (?) ORDER BY law_slug, position', [
	[...WHOLE, ...PARTS],
]);
const keptOutline = outline
	.filter((h) => WHOLE.includes(h.law_slug) || kept.has(`${h.law_slug}:${h.before_norm}`))
	.map(({ id, ...h }) => h);
await conn.end();

const counts = Object.groupBy(norms, (n) => n.law_slug);
const insert = (table, rows) =>
	rows.map((row) => mysql.format(`INSERT INTO ${table} SET ?;`, [row])).join('\n');
const sql = [
	'-- Generated by tests/fixtures/make-db-fixture.mjs. Law texts: gesetze-im-internet.de (§ 5 UrhG).',
	'SET NAMES utf8mb4;',
	insert(
		'laws',
		laws.map((l) => ({ ...l, norm_count: counts[l.slug]?.length ?? 0 })),
	),
	insert(
		'norms',
		norms.map((n) => ({ ...n, paragraphs: JSON.stringify(n.paragraphs) })),
	),
	insert('law_outline', keptOutline),
	'',
].join('\n');
writeFileSync(new URL('./laws.sql', import.meta.url), sql);
console.log(
	`${laws.length} laws, ${norms.length} norms, ${keptOutline.length} headings, ${(sql.length / 1024).toFixed(0)} KiB`,
);
